 style={{ width: "100%", padding: "12px 14px", borderRadius: 10, border: "1px solid #ddd", fontSize: 15, resize: "vertical", boxSizing: "border-box" }}
 />
 </div>

 {/* Severity */}
 <div style={{ marginBottom: 24 }}>
 <label style={{ display: "block", fontSize: 13, fontWeight: 600, color: "#444", marginBottom: 6 }}>Severity</label>
 <select
 value={severity}
 onChange={(e) => setSeverity(e.target.value)}
 style={{ width: "100%", padding: "12px 14px", borderRadius: 10, border: "1px solid #ddd", fontSize: 15, background: "#fafafa", appearance: "none" as any }}
 >
 <option value="Low">Low — Minor inconvenience</option>
 <option value="Medium">Medium — Significant issue</option>
 <option value="High">High — Safety concern</option>
 </select>
 </div>

 {/* Location indicator */}
 {latitude !== null && longitude !== null && (
 <div style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 16, fontSize: 12, color: "#388e3c" }}>
 <span>📍</span> Location captured ({latitude.toFixed(4)}, {longitude.toFixed(4)})
 </div>
 )}

 {/* Submit */}
 <button
 onClick={handleSubmit}
 disabled={submitting}
 style={{
 width: "100%",
