 { id: "mybus", label: "My Bus", icon: "M4 16V6a4 4 0 014-4h8a4 4 0 014 4v10M4 16h16M4 16l-2 3h20l-2-3M8 20v1M16 20v1M8 10h8" },
 { id: "report", label: "Report", icon: "M12 9v2m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" },
 { id: "requests", label: "Requests", icon: "M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" },
 { id: "profile", label: "Profile", icon: "M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" },
];

export default function BottomNav({ currentView, navigate }: Props) {
 const isActive = (id: string) => {
 if (id === "home" && currentView === "home") return true;
 if (id === "mybus" && (currentView === "mybus" || currentView === "buspass")) return true;
 if (id === "report" && (currentView === "report" || currentView === "issue-form")) return true;
 if (id === "requests" && (currentView === "requests" || currentView === "request-detail")) return true;
 if (id === "profile" && currentView === "profile") return true;
 return false;
 };

 return (
 <nav className="ms-bottom-nav">
 {navItems.map((item) => (
 <button
 key={item.id}
 className={`ms-nav-item ${isActive(item.id) ? "ms-nav-active" : ""}`}
 onClick={() => navigate(item.id)}
 >
