 </button>
 ))}
 </nav>
 );
}
","import React, { useState, useRef, useEffect } from "react";

/* ─── Types ─── */
interface Message {
 id: number;
 text: string;
 sender: "bot" | "user";
 options?: OptionItem[];
 resultCard?: ResultCard;
 locationBtn?: boolean;
 alternativeBuses?: string[];
}

interface OptionItem {
 label: string;
 value: string;
}

interface ResultCard {
 caseNumber: string;
 etaResponse: string;
 bus: string;
 route: string;
 stop: string;
 issueType: string;
}

type FlowStep =
 | "idle"
 | "select_bus"
 | "select_route"
 | "select_stop"
 | "describe"
 | "location"
 | "submitting"
 | "result"
 | "select_requested_route"
 | "select_requested_stop";

type IssueFlowType =
 | "bus_delay"
 | "bus_not_arrived"
 | "overcrowded"
 | "missed_bus"
 | "route_change"
 | null;

interface FlowState {
 step: FlowStep;
 flowType: IssueFlowType;
 busId: string;
 busLabel: string;
 routeId: string;
 routeLabel: string;
 stopId: string;
 stopLabel: string;
 description: string;
 latitude: string;
 longitude: string;
 requestedRouteId: string;
 requestedRouteLabel: string;
 requestedStopId: string;
 requestedStopLabel: string;
}

/* ─── Static suggestions ─── */
const SUGGESTIONS = [
 "Bus Delay",
 "Bus Not Arrived",
 "Overcrowded",
 "Missed Bus",
 "Route Change",
];

/* ─── API helpers ─── */
const API_HEADERS = (): Record<string, string> => ({
 "Content-Type": "application/json",
 Accept: "application/json",
 "X-UserToken": (window as any).g_ck || "",
});

async function fetchTableRecords(table: string, query?: string): Promise<any[]> {
 let url = `/api/now/table/${table}?sysparm_display_value=all&sysparm_limit=50`;
 if (query) url += `&sysparm_query=${encodeURIComponent(query)}`;
 const res = await fetch(url, { headers: API_HEADERS() });
 const json = await res.json();
 return json.result || [];
}

async function createRecord(table: string, body: Record<string, string>): Promise<any> {
 const res = await fetch(`/api/now/table/${table}`, {
 method: "POST",
 headers: API_HEADERS(),
 body: JSON.stringify(body),
 });
 const json = await res.json();
 return json.result;
}

async function getRecord(table: string, sysId: string): Promise<any> {
 const res = await fetch(`/api/now/table/${table}/${sysId}?sysparm_display_value=all`, {
 headers: API_HEADERS(),
 });
 const json = await res.json();
 return json.result;
}

/* ─── Static responses for non-flow options ─── */
function getStaticResponse(message: string): string {
 const lower = message.toLowerCase().trim();

 if (lower === "bus schedule" || lower.includes("schedule")) {
 return "🚌 BUS-12 Schedule:\n• Anna Nagar: 8:00 AM\n• Mogappair: 8:15 AM\n• Ambattur: 8:30 AM\n• RMD College: 8:45 AM\nNext bus arrives in 10 minutes!";
 }
 if (lower === "bus pass status" || lower.includes("pass")) {
 return "✅ Your bus pass is ACTIVE\n\n📋 Pass Details:\n• Pass ID: BP-001\n• Bus: BUS-12\n• Valid Until: March 31, 2027\n• Status: Active\n\nYour pass is valid for 287 more days.";
 }
 if (lower === "track my bus" || lower.includes("track")) {
 return "📍 BUS-12 Current Location:\n\nRoute: Anna Nagar → RMD College\n🟢 Currently at: Mogappair\n⏱ ETA to RMD College: 10 mins\n\nThe bus is running on time!";
 }

 return `I understand you're asking about "${message}". Let me help you with that.\n\nFor immediate assistance, try these options:\n• Type 'bus delay' to report a delay\n• Type 'bus not arrived' if your bus hasn't come\n• Type 'overcrowded' to report overcrowding\n• Type 'missed bus' if you missed your bus\n• Type 'route change' to request a route change`;
}

/* ─── Initial flow state ─── */
const INITIAL_FLOW: FlowState = {
 step: "idle",
 flowType: null,
 busId: "",
 busLabel: "",
 routeId: "",
 routeLabel: "",
 stopId: "",
 stopLabel: "",
 description: "",
 latitude: "",
 longitude: "",
 requestedRouteId: "",
 requestedRouteLabel: "",
 requestedStopId: "",
 requestedStopLabel: "",
};

/* ─── Helper: poll for solution_response ─── */
async function pollForSolution(sysId: string, maxAttempts = 5, intervalMs = 2000): Promise<{ solution: string; caseNumber: string }> {
 let solution = "";
 let caseNumber = "";
 for (let attempt = 0; attempt < maxAttempts; attempt++) {
 await new Promise((resolve) => setTimeout(resolve, intervalMs));
 const updated = await getRecord("u_transportation_case", sysId);
 solution = updated?.u_solution_response?.display_value || updated?.u_solution_response || "";
 caseNumber = updated?.u_case_number?.display_value || updated?.u_case_number || updated?.u_number?.display_value || updated?.u_number || "";
 if (solution) break;
 }
 return { solution, caseNumber };
}

/* ─── Helper: get flow label from type ─── */
function getFlowLabel(flowType: IssueFlowType): string {
 switch (flowType) {
 case "bus_delay": return "Bus Delay";
 case "bus_not_arrived": return "Bus Not Arrived";
 case "overcrowded": return "Overcrowded";
 case "missed_bus": return "Missed Bus";
 case "route_change": return "Route Change Request";
 default: return "Issue";
 }
}

/* ─── Helper: check if flow needs location ─── */
function flowNeedsLocation(flowType: IssueFlowType): boolean {
 return flowType === "bus_delay" || flowType === "bus_not_arrived" || flowType === "missed_bus";
}

/* ─── Helper: check if flow needs bus selection ─── */
function flowNeedsBus(flowType: IssueFlowType): boolean {
 return flowType !== "route_change";
}

/* ─── Main Component ─── */
export default function ChatWidget() {
 const [isOpen, setIsOpen] = useState(false);
 const [messages, setMessages] = useState<Message[]>([
 {
 id: 1,
 text: "Hi! 👋 I'm your MoveSmart transportation assistant. How can I help you today?",
 sender: "bot",
 },
 ]);
 const [inputValue, setInputValue] = useState("");
 const [isTyping, setIsTyping] = useState(false);
 const [flow, setFlow] = useState<FlowState>(INITIAL_FLOW);

 const messagesEndRef = useRef<HTMLDivElement>(null);
 const inputRef = useRef<HTMLInputElement>(null);

 useEffect(() => {
 messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
 }, [messages, isTyping]);

 useEffect(() => {
 if (isOpen && inputRef.current) {
 inputRef.current.focus();
 }
 }, [isOpen]);

 /* ─── Add messages helper ─── */
 const addBotMessage = (text: string, extras?: Partial<Message>) => {
 const msg: Message = {
 id: Date.now() + Math.random(),
 text,
 sender: "bot",
 ...extras,
 };
 setMessages((prev) => [...prev, msg]);
 };

 const addUserMessage = (text: string) => {
 const msg: Message = {
 id: Date.now() + Math.random(),
 text,
 sender: "user",
 };
 setMessages((prev) => [...prev, msg]);
 };

 /* ─── Start Issue Flow ─── */
 const startIssueFlow = async (issueType: IssueFlowType) => {
 const label = getFlowLabel(issueType);
 addUserMessage(label);
 setIsTyping(true);

 if (issueType === "route_change") {
 // Route Change starts with route selection, not bus
 setFlow((s) => ({ ...s, step: "select_route", flowType: issueType }));
 try {
 const routes = await fetchTableRecords("u_route");
 const options: OptionItem[] = routes.map((r: any) => ({
 label: `${r.u_route_name?.display_value || r.u_route_name || ""} (${r.u_route_id?.display_value || r.u_route_id || ""})`,
 value: r.sys_id?.value || r.sys_id,
 }));
 setIsTyping(false);
 addBotMessage("What's your current route?", { options });
 } catch {
 setIsTyping(false);
 addBotMessage("Sorry, I couldn't fetch route data. Please try again later.");
 setFlow(INITIAL_FLOW);
 }
 return;
 }

 // All other flows start with bus selection
 setFlow((s) => ({ ...s, step: "select_bus", flowType: issueType }));
 try {
 const buses = await fetchTableRecords("u_bus");
 const options: OptionItem[] = buses.map((b: any) => ({
 label: b.u_bus_number?.display_value || b.u_bus_number || "Unknown",
 value: b.sys_id?.value || b.sys_id,
 }));
 setIsTyping(false);

 let question = "Which bus are you reporting?";
 switch (issueType) {
 case "bus_delay":
 question = "Which bus are you waiting for?";
 break;
 case "bus_not_arrived":
 question = "Which bus has not arrived?";
 break;
 case "overcrowded":
 question = "Which bus is overcrowded?";
 break;
 case "missed_bus":
 question = "Which bus did you miss?";
 break;
 }
 addBotMessage(question, { options });
 } catch {
 setIsTyping(false);
 addBotMessage("Sorry, I couldn't fetch bus data. Please try again later.");
 setFlow(INITIAL_FLOW);
 }
 };

 /* ─── Bus Selected ─── */
 const handleBusSelected = async (option: OptionItem) => {
 addUserMessage(option.label);
 setFlow((s) => ({ ...s, busId: option.value, busLabel: option.label, step: "select_route" }));
 setIsTyping(true);

 try {
 const routes = await fetchTableRecords("u_route");
 const options: OptionItem[] = routes.map((r: any) => ({
 label: `${r.u_route_name?.display_value || r.u_route_name || ""} (${r.u_route_id?.display_value || r.u_route_id || ""})`,
 value: r.sys_id?.value || r.sys_id,
 }));
 setIsTyping(false);

 let question = "Which route is this bus on?";
 if (flow.flowType === "overcrowded") {
 question = "Which route is it on?";
 } else if (flow.flowType === "missed_bus") {
 question = "Which route was it on?";
 }
 addBotMessage(question, { options });
 } catch {
 setIsTyping(false);
 addBotMessage("Sorry, I couldn't fetch route data. Please try again later.");
 setFlow(INITIAL_FLOW);
 }
 };

 /* ─── Route Selected ─── */
 const handleRouteSelected = async (option: OptionItem) => {
 addUserMessage(option.label);
 setFlow((s) => ({ ...s, routeId: option.value, routeLabel: option.label, step: "select_stop" }));
 setIsTyping(true);

 try {
 const stops = await fetchTableRecords("u_bus_stop", `u_route_id=${option.value}`);
 const options: OptionItem[] = stops.map((s: any) => ({
 label: `${s.u_stop_name?.display_value || s.u_stop_name || ""} (${s.u_stop_id?.display_value || s.u_stop_id || ""})`,
 value: s.sys_id?.value || s.sys_id,
 }));
 setIsTyping(false);

 if (options.length === 0) {
 addBotMessage("No stops found for this route. Which stop are you at? (type the name)");
 } else {
 let question = "Which bus stop are you at?";
 if (flow.flowType === "bus_delay") {
 question = "Which bus stop are you waiting at?";
 } else if (flow.flowType === "bus_not_arrived") {
 question = "At which stop are you waiting for the bus?";
 } else if (flow.flowType === "overcrowded") {
 question = "Which stop are you at?";
 } else if (flow.flowType === "missed_bus") {
 question = "Which stop were you at?";
 } else if (flow.flowType === "route_change") {
 question = "What's your current bus stop?";
 }
 addBotMessage(question, { options });
 }
 } catch {
 setIsTyping(false);
 addBotMessage("Sorry, I couldn't fetch bus stop data. Please try again later.");
 setFlow(INITIAL_FLOW);
 }
 };

 /* ─── Stop Selected ─── */
 const handleStopSelected = (option: OptionItem) => {
 addUserMessage(option.label);
 setFlow((s) => ({ ...s, stopId: option.value, stopLabel: option.label }));

 if (flow.flowType === "route_change") {
 // After current stop, ask for requested route
 setFlow((s) => ({ ...s, stopId: option.value, stopLabel: option.label, step: "select_requested_route" }));
 fetchRequestedRoutes();
 return;
 }

 // Move to description step
 setFlow((s) => ({ ...s, stopId: option.value, stopLabel: option.label, step: "describe" }));
 let prompt = "Please describe the issue:";
 switch (flow.flowType) {
 case "bus_delay":
 prompt = "Please describe the delay issue (e.g., how long you've been waiting):";
 break;
 case "bus_not_arrived":
 prompt = "Please describe the situation (e.g., how long have you been waiting for the bus):";
 break;
 case "overcrowded":
 prompt = "Any additional details about the overcrowding?";
 break;
 case "missed_bus":
 prompt = "Please describe what happened (e.g., how long ago, what you observed):";
 break;
 }
 addBotMessage(prompt);
 };

 /* ─── Route Change: fetch requested routes ─── */
 const fetchRequestedRoutes = async () => {
 setIsTyping(true);
 try {
 const routes = await fetchTableRecords("u_route");
 const options: OptionItem[] = routes.map((r: any) => ({
 label: `${r.u_route_name?.display_value || r.u_route_name || ""} (${r.u_route_id?.display_value || r.u_route_id || ""})`,
 value: r.sys_id?.value || r.sys_id,
 }));
 setIsTyping(false);
 addBotMessage("Which route would you like to change to?", { options });
 } catch {
 setIsTyping(false);
 addBotMessage("Sorry, I couldn't fetch route data. Please try again later.");
 setFlow(INITIAL_FLOW);
 }
 };

 /* ─── Requested Route Selected ─── */
 const handleRequestedRouteSelected = async (option: OptionItem) => {
 addUserMessage(option.label);
 setFlow((s) => ({ ...s, requestedRouteId: option.value, requestedRouteLabel: option.label, step: "select_requested_stop" }));
 setIsTyping(true);

 try {
 const stops = await fetchTableRecords("u_bus_stop", `u_route_id=${option.value}`);
 const options: OptionItem[] = stops.map((s: any) => ({
 label: `${s.u_stop_name?.display_value || s.u_stop_name || ""} (${s.u_stop_id?.display_value || s.u_stop_id || ""})`,
 value: s.sys_id?.value || s.sys_id,
 }));
 setIsTyping(false);

 if (options.length === 0) {
 addBotMessage("No stops found for this route. Which stop on the new route? (type the name)");
 } else {
 addBotMessage("Which stop on the new route?", { options });
 }
 } catch {
 setIsTyping(false);
 addBotMessage("Sorry, I couldn't fetch bus stop data. Please try again later.");
 setFlow(INITIAL_FLOW);
 }
 };

 /* ─── Requested Stop Selected ─── */
 const handleRequestedStopSelected = (option: OptionItem) => {
 addUserMessage(option.label);
 setFlow((s) => ({ ...s, requestedStopId: option.value, requestedStopLabel: option.label, step: "describe" }));
 addBotMessage("Why do you want to change routes?");
 };

 /* ─── Description Submitted ─── */
 const handleDescriptionSubmit = (text: string) => {
 addUserMessage(text);

 if (flowNeedsLocation(flow.flowType)) {
 setFlow((s) => ({ ...s, description: text, step: "location" }));
 addBotMessage("I need your current location to process this report. Please share your location:", {
 locationBtn: true,
 });
 } else {
 // Overcrowded and Route Change don't need location
 setFlow((s) => ({ ...s, description: text, step: "submitting" }));
 submitCase(text, "", "");
 }
 };

 /* ─── Location Share ─── */
 const handleLocationShare = async () => {
 addUserMessage("📍 Location shared");
 let lat = "13.0";
 let lng = "80.2";

 if (navigator.geolocation) {
 try {
 const pos = await new Promise<GeolocationPosition>((resolve, reject) => {
 navigator.geolocation.getCurrentPosition(resolve, reject, { timeout: 5000 });
 });
 lat = pos.coords.latitude.toFixed(4);
 lng = pos.coords.longitude.toFixed(4);
 } catch {
 // Use defaults
 }
 }

 setFlow((s) => ({ ...s, latitude: lat, longitude: lng, step: "submitting" }));
 const label = getFlowLabel(flow.flowType);
 addBotMessage(`📍 Location received (${lat}, ${lng}). Creating your ${label} report...`);
 submitCase(flow.description, lat, lng);
 };

 /* ─── Submit Case ─── */
 const submitCase = async (description: string, lat: string, lng: string) => {
 setIsTyping(true);
 const flowType = flow.flowType;
 const label = getFlowLabel(flowType);

 if (!flowNeedsLocation(flowType) && !lat) {
 addBotMessage(`Submitting your ${label} report...`);
 }

 try {
 let payload: Record<string, string> = {};

 switch (flowType) {
 case "bus_delay":
 payload = {
 u_issue_type: "Bus Delay",
 u_bus_number: flow.busId,
 u_route_id: flow.routeId,
 u_bus_stop: flow.stopId,
 u_reported_latitude: lat,
 u_reported_longitude: lng,
 u_description: description,
 u_short_description: "Bus Delay Report",
 };
 break;
 case "bus_not_arrived":
 payload = {
 u_issue_type: "Bus Not Arrived",
 u_current_bus: flow.busId,
 u_current_route: flow.routeId,
 u_current_bus_stop: flow.stopId,
 u_reported_latitude: lat,
 u_reported_longitude: lng,
 u_description: description,
 u_short_description: "Bus Not Arrived Report",
 };
 break;
 case "overcrowded":
 payload = {
 u_issue_type: "Overcrowded",
 u_current_bus: flow.busId,
 u_current_route: flow.routeId,
 u_current_bus_stop: flow.stopId,
 u_description: description,
 u_short_description: "Overcrowded Bus Report",
 };
 break;
 case "missed_bus":
 payload = {
 u_issue_type: "Missed Bus",
 u_current_bus: flow.busId,
 u_current_route: flow.routeId,
 u_current_bus_stop: flow.stopId,
 u_reported_latitude: lat,
 u_reported_longitude: lng,
 u_description: description,
 u_short_description: "Missed Bus Report",
 };
 break;
 case "route_change":
 payload = {
 u_issue_type: "Route Change Request",
 u_current_route: flow.routeId,
 u_current_bus_stop: flow.stopId,
 u_requested_route: flow.requestedRouteId,
 u_requested_bus_stop: flow.requestedStopId,
 u_description: description,
 u_short_description: "Route Change Request",
 };
 break;
 }

 const record = await createRecord("u_transportation_case", payload);
 const sysId = record?.sys_id?.value || record?.sys_id;

 if (!sysId) {
 throw new Error("No sys_id returned");
 }

 // Poll for solution_response (BR/flow runs after insert)
 let caseNumber = record?.u_case_number?.display_value || record?.u_case_number || record?.u_number?.display_value || record?.u_number || "";
 const pollResult = await pollForSolution(sysId);
 const etaResponse = pollResult.solution;
 if (pollResult.caseNumber) caseNumber = pollResult.caseNumber;

 // For Overcrowded: also fetch alternative buses on the same route
 let alternativeBuses: string[] = [];
 if (flowType === "overcrowded" && flow.routeId) {
 try {
 const altQuery = `u_route=${flow.routeId}^u_is_overcrowded=false^sys_id!=${flow.busId}`;
 const altBuses = await fetchTableRecords("u_bus", altQuery);
 alternativeBuses = altBuses.map((b: any) => b.u_bus_number?.display_value || b.u_bus_number || "Unknown");
 } catch {
 // Non-critical, continue without alternatives
 }
 }

 setIsTyping(false);

 // Build result card
 const busDisplay = flow.busLabel || "N/A";
 const routeDisplay = flow.flowType === "route_change" ? `${flow.routeLabel} → ${flow.requestedRouteLabel}` : flow.routeLabel;
 const stopDisplay = flow.flowType === "route_change" ? `${flow.stopLabel} → ${flow.requestedStopLabel}` : flow.stopLabel;

 if (etaResponse || alternativeBuses.length > 0) {
 let responseText = etaResponse || "Your report has been submitted. The system is processing your case.";

 // Add alternative buses section for overcrowded
 if (alternativeBuses.length > 0) {
 responseText += `\n\n🚌 Alternative Buses Available:\n${alternativeBuses.join(", ")}`;
 }

 addBotMessage(`✅ Your "${label}" report has been filed! Here's the response:`, {
 resultCard: {
 caseNumber,
 etaResponse: responseText,
 bus: busDisplay,
 route: routeDisplay,
 stop: stopDisplay,
 issueType: label,
 },
 alternativeBuses: alternativeBuses.length > 0 ? alternativeBuses : undefined,
 });
 } else {
 addBotMessage(
 `✅ Your "${label}" report has been filed as ${caseNumber || "a new case"}. The system is processing it — check back shortly for the response.`
 );
 }

 setFlow({ ...INITIAL_FLOW, step: "result" });
 } catch (err) {
 setIsTyping(false);
 addBotMessage("❌ Sorry, I couldn't create the report. Please try again or contact support.");
 setFlow(INITIAL_FLOW);
 }
 };

 /* ─── Handle general send ─── */
 const sendMessage = (text: string) => {
 if (!text.trim()) return;
 const trimmed = text.trim();

 // If in a flow — handle step-specific input
 if (flow.step === "describe") {
 handleDescriptionSubmit(trimmed);
 setInputValue("");
 return;
 }

 if (flow.step === "select_stop" && trimmed) {
 addUserMessage(trimmed);
 if (flow.flowType === "route_change") {
 setFlow((s) => ({ ...s, stopId: "", stopLabel: trimmed, step: "select_requested_route" }));
 fetchRequestedRoutes();
 } else {
 setFlow((s) => ({ ...s, stopId: "", stopLabel: trimmed, step: "describe" }));
 let prompt = "Please describe the issue:";
 switch (flow.flowType) {
 case "bus_delay":
 prompt = "Please describe the delay issue (e.g., how long you've been waiting):";
 break;
 case "bus_not_arrived":
 prompt = "Please describe the situation (e.g., how long have you been waiting for the bus):";
 break;
 case "overcrowded":
 prompt = "Any additional details about the overcrowding?";
 break;
 case "missed_bus":
 prompt = "Please describe what happened (e.g., how long ago, what you observed):";
 break;
 }
 addBotMessage(prompt);
 }
 setInputValue("");
 return;
 }

 if (flow.step === "select_requested_stop" && trimmed) {
 addUserMessage(trimmed);
 setFlow((s) => ({ ...s, requestedStopId: "", requestedStopLabel: trimmed, step: "describe" }));
 addBotMessage("Why do you want to change routes?");
 setInputValue("");
 return;
 }

 // Start flows by text
 const lower = trimmed.toLowerCase();
 if (lower === "bus delay") {
 setInputValue("");
 startIssueFlow("bus_delay");
 return;
 }
 if (lower === "bus not arrived" || lower === "bus not arrived!") {
 setInputValue("");
 startIssueFlow("bus_not_arrived");
 return;
 }
 if (lower === "overcrowded") {
 setInputValue("");
 startIssueFlow("overcrowded");
 return;
 }
 if (lower === "missed bus") {
 setInputValue("");
 startIssueFlow("missed_bus");
 return;
 }
 if (lower === "route change" || lower === "route change request") {
 setInputValue("");
 startIssueFlow("route_change");
 return;
 }

 // Static responses for other options
 addUserMessage(trimmed);
 setInputValue("");
 setIsTyping(true);

 setTimeout(() => {
 setIsTyping(false);
 addBotMessage(getStaticResponse(trimmed));
 }, 800);
 };

 const handleSubmit = (e: React.FormEvent) => {
 e.preventDefault();
 sendMessage(inputValue);
 };

 const handleSuggestionClick = (suggestion: string) => {
 switch (suggestion) {
 case "Bus Delay":
 startIssueFlow("bus_delay");
 break;
 case "Bus Not Arrived":
 startIssueFlow("bus_not_arrived");
 break;
 case "Overcrowded":
 startIssueFlow("overcrowded");
 break;
 case "Missed Bus":
 startIssueFlow("missed_bus");
 break;
 case "Route Change":
 startIssueFlow("route_change");
 break;
 default:
 sendMessage(suggestion);
 break;
 }
 };

 const handleOptionClick = (option: OptionItem) => {
 switch (flow.step) {
 case "select_bus":
 handleBusSelected(option);
 break;
 case "select_route":
 handleRouteSelected(option);
 break;
 case "select_stop":
 handleStopSelected(option);
 break;
 case "select_requested_route":
 handleRequestedRouteSelected(option);
 break;
 case "select_requested_stop":
 handleRequestedStopSelected(option);
 break;
 }
 };

 /* ─── Format text with line breaks and bus number highlighting ─── */
 const formatMessage = (text: string) => {
 return text.split("\n").map((line, i) => {
 // Highlight bus numbers (BUS followed by digits/dashes)
 const highlighted = line.replace(/(BUS[-\s]?\d+)/gi, "⟪$1⟫");
 const parts = highlighted.split(/⟪|⟫/);
 return (
 <span key={i}>
 {parts.map((part, j) =>
 /^BUS[-\s]?\d+$/i.test(part) ? (
 <strong key={j} className="ms-chat-bus-highlight">{part}</strong>
 ) : (
 <span key={j}>{part}</span>
 )
 )}
 {i < text.split("\n").length - 1 && <br />}
 </span>
 );
 });
 };

 /* ─── Determine if options should be interactive ─── */
 const isOptionStep = (step: FlowStep): boolean => {
 return (
 step === "select_bus" ||
 step === "select_route" ||
 step === "select_stop" ||
 step === "select_requested_route" ||
 step === "select_requested_stop"
 );
 };

 /* ─── Input disabled state ─── */
 const isInputDisabled =
 isTyping ||
 flow.step === "submitting" ||
 flow.step === "location" ||
 flow.step === "select_bus" ||
 flow.step === "select_route" ||
 flow.step === "select_requested_route";

 /* ─── Input placeholder ─── */
 const getPlaceholder = (): string => {
 if (flow.step === "describe") {
 return flow.flowType === "route_change" ? "Describe why you want to change..." : "Describe the issue...";
 }
 if (flow.step === "location") return "Use the location button above";
 if (flow.step === "select_stop" || flow.step === "select_requested_stop") return "Or type a stop name...";
 return "Type a message...";
 };

 return (
 <>
 {/* Floating Action Button */}
 {!isOpen && (
 <button
 className="ms-chat-fab"
 onClick={() => setIsOpen(true)}
 aria-label="Open chat assistant"
 >
 <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
 <path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z" />
 </svg>
 <span className="ms-chat-fab-pulse"></span>
 </button>
 )}

 {/* Chat Panel */}
 {isOpen && (
 <div className="ms-chat-panel">
 {/* Header */}
 <div className="ms-chat-header">
 <div className="ms-chat-header-left">
 <div className="ms-chat-avatar">
 <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
 <rect x="3" y="11" width="18" height="10" rx="2" />
 <circle cx="12" cy="5" r="2" />
 <path d="M12 7v4" />
 <line x1="8" y1="16" x2="8" y2="16" />
 <line x1="16" y1="16" x2="16" y2="16" />
 </svg>
 </div>
 <div className="ms-chat-header-info">
 <span className="ms-chat-header-title">MoveSmart Assistant</span>
 <span className="ms-chat-header-status">Online</span>
 </div>
 </div>
 <button
 className="ms-chat-close-btn"
 onClick={() => setIsOpen(false)}
 aria-label="Close chat"
 >
 <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
 <line x1="18" y1="6" x2="6" y2="18" />
 <line x1="6" y1="6" x2="18" y2="18" />
 </svg>
 </button>
 </div>

 {/* Messages */}
 <div className="ms-chat-messages">
 {messages.map((msg) => (
 <div key={msg.id}>
 <div
 className={
 msg.sender === "bot"
 ? "ms-chat-message ms-chat-message-bot"
 : "ms-chat-message ms-chat-message-user"
 }
 >
 <div className="ms-chat-bubble">
 {formatMessage(msg.text)}
 </div>
 </div>

 {/* Render interactive options */}
 {msg.options && msg.options.length > 0 && (
 <div className="ms-chat-options">
 {msg.options.map((opt) => (
 <button
 key={opt.value}
 className="ms-chat-option-btn"
 onClick={() => handleOptionClick(opt)}
 disabled={!isOptionStep(flow.step)}
 >
 {opt.label}
 </button>
 ))}
 </div>
 )}

 {/* Location share button */}
 {msg.locationBtn && (
 <div className="ms-chat-options">
 <button
 className="ms-chat-location-btn"
 onClick={handleLocationShare}
 disabled={flow.step !== "location"}
 >
 <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
 <path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z" />
 <circle cx="12" cy="10" r="3" />
 </svg>
 Share My Location
 </button>
 </div>
 )}

 {/* Result Card */}
 {msg.resultCard && (
 <div className="ms-chat-result-card">
 <div className="ms-result-card-header">
 <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
 <circle cx="12" cy="12" r="10" />
 <polyline points="12 6 12 12 16 14" />
 </svg>
 <span className="ms-result-card-title">{msg.resultCard.issueType}</span>
 <span className="ms-result-card-case">{msg.resultCard.caseNumber}</span>
 </div>
 <div className="ms-result-card-body">
 <p className="ms-result-card-eta">{formatMessage(msg.resultCard.etaResponse)}</p>
 </div>
 <div className="ms-result-card-footer">
 <div className="ms-result-card-detail">
 <span className="ms-result-detail-label">Bus</span>
 <span className="ms-result-detail-value">{msg.resultCard.bus}</span>
 </div>
 <div className="ms-result-card-detail">
 <span className="ms-result-detail-label">Route</span>
 <span className="ms-result-detail-value">{msg.resultCard.route}</span>
 </div>
 <div className="ms-result-card-detail">
 <span className="ms-result-detail-label">Stop</span>
 <span className="ms-result-detail-value">{msg.resultCard.stop}</span>
 </div>
 </div>
 </div>
 )}
 </div>
 ))}

 {/* Typing Indicator */}
 {isTyping && (
 <div className="ms-chat-message ms-chat-message-bot">
 <div className="ms-chat-bubble ms-chat-typing">
 <span className="ms-typing-dot"></span>
 <span className="ms-typing-dot"></span>
 <span className="ms-typing-dot"></span>
 </div>
 </div>
 )}

 {/* Suggestions (show only at start and idle) */}
 {messages.length === 1 && !isTyping && flow.step === "idle" && (
 <div className="ms-chat-suggestions">
 {SUGGESTIONS.map((s) => (
 <button
 key={s}
 className="ms-chat-suggestion-chip"
 onClick={() => handleSuggestionClick(s)}
 >
 {s}
 </button>
 ))}
 </div>
 )}

 <div ref={messagesEndRef} />
 </div>

 {/* Input Area */}
 <form className="ms-chat-input-area" onSubmit={handleSubmit}>
 <input
 ref={inputRef}
 type="text"
 className="ms-chat-input"
 placeholder={getPlaceholder()}
 value={inputValue}
 onChange={(e) => setInputValue(e.target.value)}
 disabled={isInputDisabled}
 />
 <button
 type="submit"
 className="ms-chat-send-btn"
 disabled={!inputValue.trim() || isInputDisabled}
 aria-label="Send message"
 >
 <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
 <line x1="22" y1="2" x2="11" y2="13" />
 <polygon points="22 2 15 22 11 13 2 9 22 2" />
 </svg>
 </button>
 </form>
 </div>
 )}
 </>
 );
}
","import React from "react";

interface Props {
 role: "student" | "driver" | "admin";
 setRole: (role: "student" | "driver" | "admin") => void;
}

const roles: { id: "student" | "driver" | "admin"; label: string; icon: string }[] = [
 { id: "student", label: "Student", icon: "🎓" },
 { id: "driver", label: "Driver", icon: "🚗" },
 { id: "admin", label: "Admin", icon: "👔" },
];

function getActiveGradient(id: string): string {
 if (id === "student") return "linear-gradient(135deg, #0080a3 0%, #00b4d8 100%)";
 if (id === "driver") return "linear-gradient(135deg, #1e3a5f 0%, #2c5282 100%)";
 return "linear-gradient(135deg, #5b2d8e 0%, #7c3aed 100%)";
}

export default function RoleSwitcher({ role, setRole }: Props) {
 const handleSwitch = (newRole: "student" | "driver" | "admin") => {
 setRole(newRole);
 const params = new URLSearchParams(window.location.search);
 params.set("role", newRole);
 params.set("view", "home");
 const path = `${window.location.pathname}?${params}`;
 window.history.replaceState({}, "", path);
 };

 return (
 <div
 style={{
 position: "sticky",
 top: 0,
 zIndex: 100,
 backgroundColor: "#ffffff",
 padding: "8px 12px",
 borderBottom: "1px solid #e8ecf0",
 boxShadow: "0 2px 8px rgba(0,0,0,0.04)",
 }}
 >
 <div
 style={{
 display: "flex",
 alignItems: "center",
 backgroundColor: "#f0f2f5",
 borderRadius: "28px",
 padding: "4px",
 gap: "4px",
 }}
 >
 {roles.map((r) => {
 const isActive = role === r.id;
 return (
 <button
 key={r.id}
 onClick={() => handleSwitch(r.id)}
 style={{
 flex: 1,
 display: "flex",
 alignItems: "center",
 justifyContent: "center",
 gap: "6px",
 padding: "10px 12px",
 borderRadius: "24px",
 border: "none",
 cursor: "pointer",
 fontSize: "13px",
 fontWeight: isActive ? 700 : 500,
 fontFamily: "system-ui, -apple-system, 'Segoe UI', sans-serif",
 color: isActive ? "#ffffff" : "#6c757d",
 background: isActive ? getActiveGradient(r.id) : "transparent",
 boxShadow: isActive ? "0 4px 12px rgba(0,0,0,0.15)" : "none",
 transition: "all 0.25s ease",
 outline: "none",
 }}
 >
 <span style={{ fontSize: "15px" }}>{r.icon}</span>
 <span>{r.label}</span>
 </button>
 );
 })}
 </div>
 </div>
 );
}
","import React, { useState, useEffect, useRef, useCallback } from "react";

interface BusRecord {
 sys_id: string;
 u_bus_number: string;
 u_bus_status: string;
 u_current_latitude: string;
 u_current_longitude: string;
 u_last_location_update: string;
 u_route: { display_value: string; value: string };
 u_driver: { display_value: string; value: string };
}

interface CaseRecord {
 sys_id: string;
 u_number: { display_value: string };
 u_issue_type: { display_value: string };
 u_short_description: { display_value: string };
 u_description: { display_value: string };
 u_current_bus_stop: { display_value: string };
 u_state: { display_value: string };
 sys_created_on: { display_value: string };
}

const API_BASE = "/api/now/table";

function getHeaders(): Record<string, string> {
 const headers: Record<string, string> = {
 "Content-Type": "application/json",
 Accept: "application/json",
 };
 if ((window as any).g_ck) {
 headers["X-UserToken"] = (window as any).g_ck;
 }
 return headers;
}

/** Safely extract display value from a field that may be string or {display_value, value} */
function dv(field: any): string {
 if (!field) return "";
 if (typeof field === "string") return field;
 if (typeof field === "object") return field.display_value || field.value || "";
 return String(field);
}

/** Extract sys_id which may be string or {display_value, value} with display_value=all */
function getSysId(record: any): string {
 const id = record?.sys_id;
 if (!id) return "";
 if (typeof id === "string") return id;
 return id.value || id.display_value || "";
}

function getAlertBorderColor(issueType: string): string {
 const t = (issueType || "").toLowerCase();
 if (t.includes("delay")) return "#f59e0b";
 if (t.includes("not arrived")) return "#e63946";
 if (t.includes("overcrowded")) return "#e63946";
 if (t.includes("route")) return "#0080a3";
 return "#6c757d";
}

export default function DriverHome() {
 const [bus, setBus] = useState<BusRecord | null>(null);
 const [tracking, setTracking] = useState(false);
 const [position, setPosition] = useState<{ lat: string; lng: string } | null>(null);
 const [lastUpdated, setLastUpdated] = useState<number | null>(null);
 const [secondsAgo, setSecondsAgo] = useState<number>(0);
 const [notifications, setNotifications] = useState<CaseRecord[]>([]);
 const [loading, setLoading] = useState(true);
 const [geoError, setGeoError] = useState<string | null>(null);

 const positionRef = useRef<{ lat: string; lng: string } | null>(null);
 const watchIdRef = useRef<number | null>(null);
 const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
 const tickRef = useRef<ReturnType<typeof setInterval> | null>(null);

 useEffect(() => {
 const controller = new AbortController();
 const timeout = setTimeout(() => controller.abort(), 5000);
 const fetchBus = async () => {
 try {
 const res = await fetch(
 `${API_BASE}/u_bus?sysparm_limit=1&sysparm_display_value=all`,
 { headers: getHeaders(), signal: controller.signal }
 );
 const data = await res.json();
 if (data.result && data.result.length > 0) {
 setBus(data.result[0]);
 }
 } catch (e: any) {
 if (e.name !== "AbortError") console.error("Failed to fetch bus:", e);
 } finally {
 clearTimeout(timeout);
 setLoading(false);
 }
 };
 fetchBus();
 return () => { clearTimeout(timeout); controller.abort(); };
 }, []);

 useEffect(() => {
 if (!bus) return;
 const fetchNotifications = async () => {
 try {
 const query = `u_current_bus=${getSysId(bus)}^ORu_bus_number=${getSysId(bus)}`;
 const res = await fetch(
 `${API_BASE}/u_transportation_case?sysparm_query=${encodeURIComponent(query)}&sysparm_display_value=all&sysparm_limit=20&sysparm_fields=sys_id,u_number,u_issue_type,u_short_description,u_description,u_current_bus_stop,u_state,sys_created_on`,
 { headers: getHeaders() }
 );
 const data = await res.json();
 setNotifications(data.result || []);
 } catch (e) {
 console.error("Failed to fetch notifications:", e);
 }
 };
 fetchNotifications();
 }, [bus]);

 useEffect(() => {
 tickRef.current = setInterval(() => {
 if (lastUpdated) {
 setSecondsAgo(Math.floor((Date.now() - lastUpdated) / 1000));
 }
 }, 1000);
 return () => { if (tickRef.current) clearInterval(tickRef.current); };
 }, [lastUpdated]);

 const patchLocation = useCallback(async () => {
 if (!bus || !positionRef.current) return;
 const now = new Date();
 const timestamp = now.toISOString().replace("T", " ").substring(0, 19);
 try {
 await fetch(`${API_BASE}/u_bus/${getSysId(bus)}`, {
 method: "PATCH",
 headers: getHeaders(),
 body: JSON.stringify({
 u_current_latitude: positionRef.current.lat,
 u_current_longitude: positionRef.current.lng,
 u_last_location_update: timestamp,
 }),
 });
 setLastUpdated(Date.now());
 } catch (e) {
 console.error("Failed to PATCH location:", e);
 }
 }, [bus]);

 const toggleTracking = useCallback(() => {
 if (tracking) {
 if (watchIdRef.current !== null) {
 navigator.geolocation.clearWatch(watchIdRef.current);
 watchIdRef.current = null;
 }
 if (intervalRef.current) {
 clearInterval(intervalRef.current);
 intervalRef.current = null;
 }
 setTracking(false);
 setGeoError(null);
 } else {
 if (!navigator.geolocation) {
 setGeoError("Geolocation is not supported by your browser.");
 return;
 }
 setGeoError(null);
 const watchId = navigator.geolocation.watchPosition(
 (pos) => {
 const lat = pos.coords.latitude.toFixed(6);
 const lng = pos.coords.longitude.toFixed(6);
 positionRef.current = { lat, lng };
 setPosition({ lat, lng });
 setGeoError(null);
 },
 (err) => {
 if (err.code === 1) setGeoError("Location permission denied. Please enable location access.");
 else if (err.code === 2) setGeoError("Unable to determine your location.");
 else setGeoError("Location request timed out.");
 },
 { enableHighAccuracy: true, maximumAge: 0, timeout: 10000 }
 );
 watchIdRef.current = watchId;
 intervalRef.current = setInterval(() => { patchLocation(); }, 2000);
 setTracking(true);
 }
 }, [tracking, patchLocation]);

 useEffect(() => {
 return () => {
 if (watchIdRef.current !== null) navigator.geolocation.clearWatch(watchIdRef.current);
 if (intervalRef.current) clearInterval(intervalRef.current);
 };
 }, []);

 // ===== STYLES =====
 const screenStyle: React.CSSProperties = {
 minHeight: "100vh",
 backgroundColor: "#f4f6f9",
 fontFamily: "system-ui, -apple-system, 'Segoe UI', sans-serif",
 paddingBottom: "80px",
 };

 if (loading) {
 return (
 <div style={screenStyle}>
 <div style={{ padding: "24px 16px", display: "flex", alignItems: "center", gap: "12px", backgroundColor: "#fff", borderBottom: "1px solid #e8ecf0" }}>
 <span style={{ fontSize: "28px" }}>🚌</span>
 <div>
 <div style={{ fontSize: "12px", color: "#6c757d", fontWeight: 500 }}>Loading</div>
 <div style={{ fontSize: "20px", fontWeight: 700, color: "#1e3a5f" }}>Driver Dashboard</div>
 </div>
 </div>
 <div style={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: "80px 20px", gap: "16px" }}>
 <div style={{ width: "40px", height: "40px", border: "4px solid #e8ecf0", borderTopColor: "#1e3a5f", borderRadius: "50%", animation: "spin 0.8s linear infinite" }} />
 <p style={{ color: "#6c757d", fontSize: "14px", margin: 0 }}>Preparing your dashboard...</p>
 </div>
 </div>
 );
 }

 return (
 <div style={screenStyle}>
 {/* Header */}
 <div style={{
