 <div style={{ position: "absolute", top: "50%", left: 0, right: 0, height: "1px", backgroundColor: "#ffffff" }} />
 <div style={{ position: "absolute", top: "75%", left: 0, right: 0, height: "1px", backgroundColor: "#ffffff" }} />
 <div style={{ position: "absolute", left: "25%", top: 0, bottom: 0, width: "1px", backgroundColor: "#ffffff" }} />
 <div style={{ position: "absolute", left: "50%", top: 0, bottom: 0, width: "1px", backgroundColor: "#ffffff" }} />
 <div style={{ position: "absolute", left: "75%", top: 0, bottom: 0, width: "1px", backgroundColor: "#ffffff" }} />
 </div>
 {/* Pulsing dot in center */}
 <div style={{ display: "flex", justifyContent: "center", marginBottom: "14px", position: "relative", zIndex: 1 }}>
 <div style={{
 width: "16px",
 height: "16px",
 borderRadius: "50%",
 backgroundColor: "#28a745",
 boxShadow: "0 0 0 6px rgba(40,167,69,0.3), 0 0 0 12px rgba(40,167,69,0.1)",
 }} />
 </div>
 {/* Coordinates Row */}
 <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", position: "relative", zIndex: 1 }}>
 <div style={{ textAlign: "center", flex: 1 }}>
 <div style={{ fontSize: "10px", color: "rgba(255,255,255,0.5)", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.5px" }}>LAT</div>
 <div style={{ fontSize: "14px", color: "#ffffff", fontWeight: 700, marginTop: "4px", fontFamily: "'SF Mono', 'Fira Code', monospace" }}>{position.lat}</div>
 </div>
 <div style={{ width: "1px", height: "28px", backgroundColor: "rgba(255,255,255,0.2)" }} />
 <div style={{ textAlign: "center", flex: 1 }}>
 <div style={{ fontSize: "10px", color: "rgba(255,255,255,0.5)", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.5px" }}>LNG</div>
 <div style={{ fontSize: "14px", color: "#ffffff", fontWeight: 700, marginTop: "4px", fontFamily: "'SF Mono', 'Fira Code', monospace" }}>{position.lng}</div>
 </div>
 {lastUpdated && (
 <>
 <div style={{ width: "1px", height: "28px", backgroundColor: "rgba(255,255,255,0.2)" }} />
 <div style={{ textAlign: "center", flex: 1 }}>
 <div style={{ fontSize: "10px", color: "rgba(255,255,255,0.5)", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.5px" }}>SYNC</div>
 <div style={{ fontSize: "14px", color: "#4ade80", fontWeight: 700, marginTop: "4px" }}>{secondsAgo}s ago</div>
 </div>
 </>
 )}
 </div>
 </div>
 )}
 </div>
 </div>

 {/* Notifications Section */}
 <div style={{ padding: "0 16px 16px" }}>
 <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: "12px" }}>
 <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
 <span style={{ fontSize: "16px" }}>🔔</span>
 <span style={{ fontSize: "16px", fontWeight: 700, color: "#1a1a2e" }}>Alerts</span>
 </div>
 <div style={{
 backgroundColor: notifications.length > 0 ? "#e63946" : "#28a745",
 color: "#ffffff",
 borderRadius: "12px",
 padding: "2px 10px",
 fontSize: "12px",
 fontWeight: 700,
 minWidth: "24px",
 textAlign: "center",
 }}>{notifications.length}</div>
 </div>

 {notifications.length === 0 ? (
 <div style={{
 backgroundColor: "#ffffff",
 borderRadius: "16px",
 padding: "32px 20px",
 textAlign: "center",
 boxShadow: "0 2px 12px rgba(0,0,0,0.08)",
 border: "1px solid #e8ecf0",
 }}>
 <span style={{ fontSize: "36px", display: "block", marginBottom: "12px" }}>✅</span>
 <p style={{ fontSize: "15px", fontWeight: 600, color: "#1a1a2e", margin: "0 0 4px" }}>All Clear!</p>
 <p style={{ fontSize: "13px", color: "#6c757d", margin: 0 }}>No active reports for your bus. You're good to go.</p>
 </div>
 ) : (
 <div style={{ display: "flex", flexDirection: "column", gap: "10px" }}>
 {notifications.map((n) => {
 const borderColor = getAlertBorderColor(n.u_issue_type?.display_value);
 return (
 <div key={getSysId(n)} style={{
 backgroundColor: "#ffffff",
 borderRadius: "14px",
 padding: "14px 16px",
 boxShadow: "0 2px 8px rgba(0,0,0,0.06)",
 borderLeft: `4px solid ${borderColor}`,
 border: "1px solid #e8ecf0",
 borderLeftColor: borderColor,
 borderLeftWidth: "4px",
 }}>
 <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: "8px" }}>
 <span style={{
 fontSize: "11px",
 fontWeight: 700,
 color: borderColor,
 backgroundColor: `${borderColor}15`,
 padding: "3px 8px",
 borderRadius: "6px",
 textTransform: "uppercase",
 letterSpacing: "0.3px",
 }}>
 {n.u_issue_type?.display_value || "Issue"}
 </span>
 <span style={{ fontSize: "11px", color: "#adb5bd" }}>{n.sys_created_on?.display_value || ""}</span>
 </div>
 <p style={{ fontSize: "14px", color: "#1a1a2e", margin: "0 0 6px", fontWeight: 500, lineHeight: "1.4" }}>
 {n.u_short_description?.display_value || "Report"}
 </p>
 {n.u_current_bus_stop?.display_value && (
 <div style={{ display: "flex", alignItems: "center", gap: "4px" }}>
 <span style={{ fontSize: "12px" }}>📍</span>
 <span style={{ fontSize: "12px", color: "#6c757d" }}>{n.u_current_bus_stop.display_value}</span>
 </div>
 )}
 </div>
 );
 })}
 </div>
 )}
 </div>
 </div>
 );
}
","import React from "react";

interface Props {
 currentView: string;
 navigate: (view: string) => void;
}

const navItems = [
 { id: "home", label: "Dashboard", emoji: "🏠" },
 { id: "tracking", label: "Tracking", emoji: "📍" },
 { id: "alerts", label: "Alerts", emoji: "🔔" },
];

export default function DriverNav({ currentView, navigate }: Props) {
 return (
 <nav className="ms-bottom-nav">
 {navItems.map((item) => (
 <button
 key={item.id}
 className={`ms-nav-item ${currentView === item.id ? "ms-nav-active" : ""}`}
 onClick={() => navigate(item.id)}
 >
 <span style={{ fontSize: "1.25rem" }}>{item.emoji}</span>
 <span className="ms-nav-label">{item.label}</span>
 </button>
 ))}
 </nav>
 );
}
","import React, { useState, useEffect } from "react";

interface CaseRecord {
 sys_id: string;
 u_number: { display_value: string };
 u_case_number: { display_value: string };
 u_issue_type: { display_value: string };
 u_state: { display_value: string };
 u_priority: { display_value: string };
 u_short_description: { display_value: string };
 u_description: { display_value: string };
 u_solution_response: { display_value: string };
 u_resolution_notes: { display_value: string };
 u_current_bus: { display_value: string };
 u_current_route: { display_value: string };
 u_current_bus_stop: { display_value: string };
 sys_created_on: { display_value: string };
}

const API_BASE = "/api/now/table";

function getHeaders(): Record<string, string> {
 const headers: Record<string, string> = {
 "Content-Type": "application/json",
 Accept: "application/json",
 };
 if ((window as any).g_ck) {
 headers["X-UserToken"] = (window as any).g_ck;
 }
 return headers;
}

const issueTypes = ["All", "Bus Delay", "Bus Not Arrived", "Overcrowded", "Route Change"];
const stateFilters = ["All States", "Open", "In Progress", "Resolved", "Approved"];

function getIssueIcon(issueType: string): string {
 const t = issueType?.toLowerCase() || "";
 if (t.includes("delay")) return "⏱️";
 if (t.includes("not arrived")) return "🚫";
 if (t.includes("overcrowded")) return "👥";
 if (t.includes("route")) return "🔄";
 return "📋";
}

function getIssueBorderColor(issueType: string): string {
 const t = issueType?.toLowerCase() || "";
 if (t.includes("delay")) return "#f59e0b";
 if (t.includes("not arrived")) return "#e63946";
 if (t.includes("overcrowded")) return "#e63946";
 if (t.includes("route")) return "#0080a3";
 return "#6c757d";
}

function getStateBadgeStyle(state: string): React.CSSProperties {
 const s = state?.toLowerCase() || "";
 if (s.includes("open")) return { backgroundColor: "#fff3cd", color: "#856404" };
 if (s.includes("progress")) return { backgroundColor: "#cce5ff", color: "#004085" };
 if (s.includes("resolved")) return { backgroundColor: "#d4edda", color: "#155724" };
 if (s.includes("approved")) return { backgroundColor: "#d4edda", color: "#155724" };
 return { backgroundColor: "#f0f2f5", color: "#6c757d" };
}

export default function AdminHome() {
 const [cases, setCases] = useState<CaseRecord[]>([]);
 const [loading, setLoading] = useState(true);
 const [selectedIssueType, setSelectedIssueType] = useState("All");
 const [selectedState, setSelectedState] = useState("All States");
 const [selectedCase, setSelectedCase] = useState<CaseRecord | null>(null);
 const [actionLoading, setActionLoading] = useState(false);

 const fetchCases = async () => {
 try {
 const res = await fetch(
 `${API_BASE}/u_transportation_case?sysparm_display_value=all&sysparm_limit=50&sysparm_query=ORDERBYDESCsys_created_on`,
 { headers: getHeaders() }
 );
 const data = await res.json();
 setCases(data.result || []);
 } catch (e) {
 console.error("Failed to fetch cases:", e);
 } finally {
 setLoading(false);
 }
 };

 useEffect(() => { fetchCases(); }, []);

 const filteredCases = cases.filter((c) => {
 const typeMatch = selectedIssueType === "All" || (c.u_issue_type?.display_value || "").toLowerCase().includes(selectedIssueType.toLowerCase());
 const stateMatch = selectedState === "All States" || (c.u_state?.display_value || "").toLowerCase().includes(selectedState.toLowerCase());
 return typeMatch && stateMatch;
 });

 const openCount = cases.filter((c) => (c.u_state?.display_value || "").toLowerCase().includes("open")).length;
 const resolvedCount = cases.filter((c) => {
 const s = (c.u_state?.display_value || "").toLowerCase();
 return s.includes("resolved") || s.includes("approved");
 }).length;

 const handleAction = async (caseRecord: CaseRecord, newState: string) => {
 setActionLoading(true);
 try {
 await fetch(`${API_BASE}/u_transportation_case/${caseRecord.sys_id}`, {
 method: "PATCH",
 headers: getHeaders(),
 body: JSON.stringify({ u_state: newState }),
 });
 await fetchCases();
 setSelectedCase(null);
 } catch (e) {
 console.error("Failed to update case:", e);
 } finally {
 setActionLoading(false);
 }
 };

 const screenStyle: React.CSSProperties = {
 minHeight: "100vh",
 backgroundColor: "#f4f6f9",
 fontFamily: "system-ui, -apple-system, 'Segoe UI', sans-serif",
 paddingBottom: "80px",
 };

 if (loading) {
 return (
 <div style={screenStyle}>
 <div style={{ padding: "20px 16px", display: "flex", alignItems: "center", gap: "12px", backgroundColor: "#fff", borderBottom: "1px solid #e8ecf0" }}>
 <span style={{ fontSize: "26px" }}>📊</span>
 <div>
 <div style={{ fontSize: "12px", color: "#6c757d", fontWeight: 500 }}>Loading</div>
 <div style={{ fontSize: "20px", fontWeight: 700, color: "#5b2d8e" }}>Admin Console</div>
 </div>
 </div>
 <div style={{ display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: "80px 20px", gap: "16px" }}>
 <div style={{ width: "40px", height: "40px", border: "4px solid #e8ecf0", borderTopColor: "#5b2d8e", borderRadius: "50%", animation: "spin 0.8s linear infinite" }} />
 <p style={{ color: "#6c757d", fontSize: "14px", margin: 0 }}>Loading cases...</p>
 </div>
 </div>
 );
 }

 return (
 <div style={screenStyle}>
 {/* Header */}
 <div style={{
 backgroundColor: "#ffffff",
 padding: "20px 16px",
 borderBottom: "1px solid #e8ecf0",
 display: "flex",
 alignItems: "center",
 justifyContent: "space-between",
 }}>
 <div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
 <div style={{
 width: "44px",
 height: "44px",
 borderRadius: "12px",
 background: "linear-gradient(135deg, #5b2d8e 0%, #7c3aed 100%)",
 display: "flex",
 alignItems: "center",
 justifyContent: "center",
 fontSize: "20px",
 }}>📊</div>
 <div>
 <div style={{ fontSize: "12px", color: "#6c757d", fontWeight: 500, letterSpacing: "0.5px", textTransform: "uppercase" }}>Transportation</div>
 <div style={{ fontSize: "20px", fontWeight: 700, color: "#1a1a2e" }}>Admin Console</div>
 </div>
 </div>
 <button
 onClick={() => { setLoading(true); fetchCases(); }}
 style={{
 width: "38px",
 height: "38px",
 borderRadius: "10px",
 border: "1px solid #e8ecf0",
 backgroundColor: "#f8f9fa",
 display: "flex",
 alignItems: "center",
 justifyContent: "center",
 cursor: "pointer",
 fontSize: "18px",
 }}
 >🔄</button>
 </div>

 {/* Stats Row */}
 <div style={{ display: "flex", gap: "10px", padding: "16px" }}>
 <div style={{
 flex: 1,
 backgroundColor: "#ffffff",
 borderRadius: "14px",
 padding: "16px 12px",
 textAlign: "center",
 boxShadow: "0 2px 8px rgba(0,0,0,0.06)",
 border: "1px solid #e8ecf0",
 }}>
