 style={{
 padding: "7px 14px",
 borderRadius: "20px",
 border: "none",
 fontSize: "12px",
 fontWeight: 600,
 cursor: "pointer",
 fontFamily: "system-ui, -apple-system, 'Segoe UI', sans-serif",
 backgroundColor: isActive ? "#5b2d8e" : "#f0f2f5",
 color: isActive ? "#ffffff" : "#495057",
 boxShadow: isActive ? "0 2px 8px rgba(91,45,142,0.3)" : "none",
 transition: "all 0.2s ease",
 outline: "none",
 }}
 >{t}</button>
 );
 })}
 </div>
 </div>

 {/* Filters: State */}
 <div style={{ padding: "0 16px 16px" }}>
 <div style={{ fontSize: "12px", fontWeight: 600, color: "#6c757d", marginBottom: "8px", textTransform: "uppercase", letterSpacing: "0.5px" }}>State</div>
 <div style={{ display: "flex", gap: "6px", flexWrap: "wrap" }}>
 {stateFilters.map((s) => {
 const isActive = selectedState === s;
 return (
 <button
 key={s}
 onClick={() => setSelectedState(s)}
 style={{
 padding: "7px 14px",
 borderRadius: "20px",
 border: "none",
 fontSize: "12px",
 fontWeight: 600,
 cursor: "pointer",
 fontFamily: "system-ui, -apple-system, 'Segoe UI', sans-serif",
 backgroundColor: isActive ? "#5b2d8e" : "#f0f2f5",
 color: isActive ? "#ffffff" : "#495057",
 boxShadow: isActive ? "0 2px 8px rgba(91,45,142,0.3)" : "none",
 transition: "all 0.2s ease",
 outline: "none",
 }}
 >{s}</button>
 );
 })}
 </div>
 </div>

 {/* Case Count */}
 <div style={{ padding: "0 16px 10px" }}>
 <span style={{ fontSize: "13px", color: "#6c757d", fontWeight: 500 }}>
 Showing {filteredCases.length} of {cases.length} cases
 </span>
 </div>

 {/* Case List */}
 <div style={{ padding: "0 16px 16px", display: "flex", flexDirection: "column", gap: "10px" }}>
 {filteredCases.length === 0 ? (
 <div style={{
 backgroundColor: "#ffffff",
 borderRadius: "16px",
 padding: "40px 20px",
 textAlign: "center",
 boxShadow: "0 2px 12px rgba(0,0,0,0.08)",
 border: "1px solid #e8ecf0",
 }}>
 <span style={{ fontSize: "40px", display: "block", marginBottom: "12px" }}>🔍</span>
 <p style={{ fontSize: "16px", fontWeight: 600, color: "#1a1a2e", margin: "0 0 4px" }}>No cases found</p>
 <p style={{ fontSize: "13px", color: "#6c757d", margin: 0 }}>Try adjusting your filters to see more results.</p>
 </div>
 ) : (
 filteredCases.map((c) => {
 const borderColor = getIssueBorderColor(c.u_issue_type?.display_value);
 const stateBadge = getStateBadgeStyle(c.u_state?.display_value);
 return (
 <div
 key={c.sys_id}
 onClick={() => setSelectedCase(c)}
 style={{
 backgroundColor: "#ffffff",
 borderRadius: "14px",
 padding: "16px",
 boxShadow: "0 2px 8px rgba(0,0,0,0.06)",
 borderLeft: `4px solid ${borderColor}`,
 cursor: "pointer",
 transition: "box-shadow 0.2s ease, transform 0.1s ease",
 }}
 >
 <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", marginBottom: "8px" }}>
 <span style={{ fontSize: "12px", fontWeight: 700, color: "#5b2d8e" }}>
 {c.u_number?.display_value || c.u_case_number?.display_value || "—"}
 </span>
 <span style={{
 fontSize: "11px",
 fontWeight: 600,
 padding: "3px 10px",
 borderRadius: "10px",
 ...stateBadge,
 }}>
 {c.u_state?.display_value || "Open"}
 </span>
 </div>
 <div style={{ fontSize: "14px", fontWeight: 600, color: "#1a1a2e", marginBottom: "10px", lineHeight: "1.4" }}>
 {c.u_short_description?.display_value || "No description"}
 </div>
 <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
 <span style={{
 fontSize: "11px",
 fontWeight: 600,
 color: borderColor,
 backgroundColor: `${borderColor}15`,
 padding: "3px 8px",
 borderRadius: "6px",
 }}>
 {getIssueIcon(c.u_issue_type?.display_value)} {c.u_issue_type?.display_value || "—"}
 </span>
 <span style={{ fontSize: "11px", color: "#adb5bd" }}>
 {c.sys_created_on?.display_value || ""}
 </span>
 </div>
 {c.u_current_bus?.display_value && (
 <div style={{ display: "flex", alignItems: "center", gap: "4px", marginTop: "8px" }}>
 <span style={{ fontSize: "12px" }}>🚌</span>
 <span style={{ fontSize: "12px", color: "#6c757d" }}>{c.u_current_bus.display_value}</span>
 </div>
 )}
 </div>
 );
 })
 )}
 </div>

 {/* Case Detail Modal */}
 {selectedCase && (
 <div
 onClick={() => setSelectedCase(null)}
 style={{
 position: "fixed",
 inset: 0,
 backgroundColor: "rgba(0,0,0,0.5)",
 zIndex: 1000,
 display: "flex",
 alignItems: "flex-end",
 justifyContent: "center",
 }}
 >
 <div
 onClick={(e) => e.stopPropagation()}
 style={{
 backgroundColor: "#ffffff",
 borderRadius: "24px 24px 0 0",
 width: "100%",
 maxWidth: "480px",
 maxHeight: "85vh",
 overflowY: "auto",
 boxShadow: "0 -8px 30px rgba(0,0,0,0.15)",
 }}
 >
 {/* Modal Header */}
 <div style={{
 padding: "20px 20px 16px",
 borderBottom: "1px solid #e8ecf0",
 display: "flex",
 alignItems: "flex-start",
 justifyContent: "space-between",
 position: "sticky",
 top: 0,
 backgroundColor: "#ffffff",
 borderRadius: "24px 24px 0 0",
 zIndex: 1,
 }}>
 <div>
 <div style={{ fontSize: "13px", fontWeight: 700, color: "#5b2d8e", marginBottom: "4px" }}>
 {selectedCase.u_number?.display_value || selectedCase.u_case_number?.display_value}
 </div>
 <div style={{ fontSize: "17px", fontWeight: 700, color: "#1a1a2e", lineHeight: "1.3" }}>
 {selectedCase.u_short_description?.display_value || "Case Detail"}
 </div>
 </div>
 <button
 onClick={() => setSelectedCase(null)}
 style={{
 width: "32px",
 height: "32px",
 borderRadius: "50%",
 border: "none",
 backgroundColor: "#f0f2f5",
 cursor: "pointer",
 display: "flex",
 alignItems: "center",
 justifyContent: "center",
 fontSize: "16px",
 color: "#6c757d",
 fontWeight: 700,
 flexShrink: 0,
 }}
 >✕</button>
 </div>

 {/* Modal Body */}
 <div style={{ padding: "16px 20px" }}>
 {/* Fields Grid */}
 <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "12px", marginBottom: "16px" }}>
 <div style={{ backgroundColor: "#f8f9fa", borderRadius: "10px", padding: "10px 12px" }}>
 <div style={{ fontSize: "10px", color: "#6c757d", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.3px", marginBottom: "4px" }}>Type</div>
 <div style={{ fontSize: "13px", fontWeight: 600, color: getIssueBorderColor(selectedCase.u_issue_type?.display_value) }}>
 {getIssueIcon(selectedCase.u_issue_type?.display_value)} {selectedCase.u_issue_type?.display_value || "—"}
 </div>
 </div>
 <div style={{ backgroundColor: "#f8f9fa", borderRadius: "10px", padding: "10px 12px" }}>
 <div style={{ fontSize: "10px", color: "#6c757d", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.3px", marginBottom: "4px" }}>State</div>
 <span style={{ fontSize: "12px", fontWeight: 600, padding: "2px 8px", borderRadius: "8px", ...getStateBadgeStyle(selectedCase.u_state?.display_value) }}>
 {selectedCase.u_state?.display_value || "—"}
 </span>
 </div>
 <div style={{ backgroundColor: "#f8f9fa", borderRadius: "10px", padding: "10px 12px" }}>
 <div style={{ fontSize: "10px", color: "#6c757d", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.3px", marginBottom: "4px" }}>Priority</div>
 <div style={{ fontSize: "13px", fontWeight: 600, color: "#1a1a2e" }}>{selectedCase.u_priority?.display_value || "—"}</div>
 </div>
 <div style={{ backgroundColor: "#f8f9fa", borderRadius: "10px", padding: "10px 12px" }}>
 <div style={{ fontSize: "10px", color: "#6c757d", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.3px", marginBottom: "4px" }}>Bus</div>
 <div style={{ fontSize: "13px", fontWeight: 600, color: "#1a1a2e" }}>{selectedCase.u_current_bus?.display_value || "—"}</div>
 </div>
 <div style={{ backgroundColor: "#f8f9fa", borderRadius: "10px", padding: "10px 12px" }}>
 <div style={{ fontSize: "10px", color: "#6c757d", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.3px", marginBottom: "4px" }}>Route</div>
 <div style={{ fontSize: "13px", fontWeight: 600, color: "#1a1a2e" }}>{selectedCase.u_current_route?.display_value || "—"}</div>
 </div>
 <div style={{ backgroundColor: "#f8f9fa", borderRadius: "10px", padding: "10px 12px" }}>
 <div style={{ fontSize: "10px", color: "#6c757d", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.3px", marginBottom: "4px" }}>Stop</div>
 <div style={{ fontSize: "13px", fontWeight: 600, color: "#1a1a2e" }}>{selectedCase.u_current_bus_stop?.display_value || "—"}</div>
 </div>
 </div>

 {/* Reported date */}
 <div style={{ backgroundColor: "#f8f9fa", borderRadius: "10px", padding: "10px 12px", marginBottom: "16px" }}>
 <div style={{ fontSize: "10px", color: "#6c757d", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.3px", marginBottom: "4px" }}>Reported</div>
 <div style={{ fontSize: "13px", fontWeight: 600, color: "#1a1a2e" }}>{selectedCase.sys_created_on?.display_value || "—"}</div>
 </div>

 {/* Description */}
 {selectedCase.u_description?.display_value && (
 <div style={{ marginBottom: "16px" }}>
 <div style={{ fontSize: "11px", color: "#6c757d", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.3px", marginBottom: "6px" }}>Description</div>
 <p style={{ fontSize: "13px", color: "#1a1a2e", lineHeight: "1.5", margin: 0, backgroundColor: "#f8f9fa", borderRadius: "10px", padding: "12px" }}>
 {selectedCase.u_description.display_value}
 </p>
 </div>
 )}

 {/* Solution Response */}
 {selectedCase.u_solution_response?.display_value && (
 <div style={{ marginBottom: "16px" }}>
 <div style={{ fontSize: "11px", color: "#6c757d", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.3px", marginBottom: "6px" }}>Solution Response</div>
 <p style={{ fontSize: "13px", color: "#1a1a2e", lineHeight: "1.5", margin: 0, backgroundColor: "#e8f8ef", borderRadius: "10px", padding: "12px", border: "1px solid #c3e6cb" }}>
 {selectedCase.u_solution_response.display_value}
 </p>
 </div>
 )}

 {/* Resolution Notes */}
 {selectedCase.u_resolution_notes?.display_value && (
 <div style={{ marginBottom: "16px" }}>
 <div style={{ fontSize: "11px", color: "#6c757d", fontWeight: 600, textTransform: "uppercase", letterSpacing: "0.3px", marginBottom: "6px" }}>Resolution Notes</div>
 <p style={{ fontSize: "13px", color: "#1a1a2e", lineHeight: "1.5", margin: 0, backgroundColor: "#e8f8ef", borderRadius: "10px", padding: "12px", border: "1px solid #c3e6cb" }}>
 {selectedCase.u_resolution_notes.display_value}
 </p>
 </div>
 )}
 </div>

 {/* Modal Actions */}
 <div style={{
 padding: "16px 20px 24px",
 borderTop: "1px solid #e8ecf0",
 display: "flex",
 gap: "10px",
 position: "sticky",
 bottom: 0,
 backgroundColor: "#ffffff",
 }}>
 <button
 disabled={actionLoading}
 onClick={() => handleAction(selectedCase, "approved")}
 style={{
 flex: 1,
 padding: "14px 16px",
 borderRadius: "12px",
 border: "none",
 background: "linear-gradient(135deg, #0080a3 0%, #00b4d8 100%)",
 color: "#ffffff",
 fontSize: "14px",
 fontWeight: 700,
 cursor: actionLoading ? "not-allowed" : "pointer",
 opacity: actionLoading ? 0.6 : 1,
 boxShadow: "0 4px 12px rgba(0,128,163,0.3)",
 fontFamily: "system-ui, -apple-system, 'Segoe UI', sans-serif",
 }}
 >✓ Approve</button>
 <button
 disabled={actionLoading}
 onClick={() => handleAction(selectedCase, "resolved")}
 style={{
 flex: 1,
 padding: "14px 16px",
 borderRadius: "12px",
 border: "none",
 background: "linear-gradient(135deg, #28a745 0%, #20c997 100%)",
 color: "#ffffff",
 fontSize: "14px",
 fontWeight: 700,
 cursor: actionLoading ? "not-allowed" : "pointer",
 opacity: actionLoading ? 0.6 : 1,
 boxShadow: "0 4px 12px rgba(40,167,69,0.3)",
 fontFamily: "system-ui, -apple-system, 'Segoe UI', sans-serif",
 }}
 >✓ Resolve</button>
 </div>
 </div>
 </div>
 )}
 </div>
 );
}
","import React from "react";

interface Props {
 currentView: string;
 navigate: (view: string) => void;
}

const navItems = [
 { id: "home", label: "Cases", emoji: "📊" },
 { id: "stats", label: "Stats", emoji: "📈" },
 { id: "settings", label: "Settings", emoji: "⚙️" },
];

export default function AdminNav({ currentView, navigate }: Props) {
 return (
 <nav className="ms-bottom-nav">
 {navItems.map((item) => (
 <button
 key={item.id}
 className={`ms-nav-item ${currentView === item.id ? "ms-nav-active" : ""}`}
 onClick={() => navigate(item.id)}
 >
 <span style={{ fontSize: "1.25rem" }}>{item.emoji}</span>
 <span className="ms-nav-label">{item.label}</span>
 </button>
 ))}
 </nav>
 );
}
","import React, { useState, useEffect, useCallback } from "react";
import "./styles.css";
import HomeScreen from "./components/HomeScreen";
import ReportIssueScreen from "./components/ReportIssueScreen";
import IssueFormScreen from "./components/IssueFormScreen";
import MyBusScreen from "./components/MyBusScreen";
import BusPassScreen from "./components/BusPassScreen";
import MyRequestsScreen from "./components/MyRequestsScreen";
import RequestDetailScreen from "./components/RequestDetailScreen";
import LostFoundScreen from "./components/LostFoundScreen";
import EmergencyScreen from "./components/EmergencyScreen";
import ProfileScreen from "./components/ProfileScreen";
import BottomNav from "./components/BottomNav";
import ChatWidget from "./components/ChatWidget";
import RoleSwitcher from "./components/RoleSwitcher";
import DriverHome from "./components/DriverHome";
import DriverNav from "./components/DriverNav";
import AdminHome from "./components/AdminHome";
import AdminNav from "./components/AdminNav";

type Role = "student" | "driver" | "admin";

interface ViewState {
 view: string;
 type: string | null;
 id: string | null;
}

function getRoleFromUrl(): Role {
 const params = new URLSearchParams(window.location.search);
 const role = params.get("role");
 if (role === "driver" || role === "admin") return role;
 return "student";
}

function getViewFromUrl(): ViewState {
 const params = new URLSearchParams(window.location.search);
 return {
 view: params.get("view") || "home",
 type: params.get("type") || null,
 id: params.get("id") || null,
 };
}

export default function App() {
 const [role, setRole] = useState<Role>(getRoleFromUrl);
 const [currentView, setCurrentView] = useState<ViewState>(getViewFromUrl);

 useEffect(() => {
 const onPopState = () => {
 setCurrentView(getViewFromUrl());
 setRole(getRoleFromUrl());
 };
 window.addEventListener("popstate", onPopState);
 return () => window.removeEventListener("popstate", onPopState);
 }, []);

 const navigate = useCallback(
 (viewName: string, extras?: { type?: string; id?: string }) => {
 const params = new URLSearchParams(window.location.search);
 params.set("view", viewName);
 if (extras?.type) {
 params.set("type", extras.type);
 } else {
 params.delete("type");
 }
 if (extras?.id) {
 params.set("id", extras.id);
 } else {
 params.delete("id");
 }
 const path = `${window.location.pathname}?${params}`;
 window.history.pushState({}, "", path);
 setCurrentView({
 view: viewName,
 type: extras?.type || null,
 id: extras?.id || null,
 });
 },
 []
 );

 const { view, type, id } = currentView;

 // Student screens
 const renderStudentScreen = () => {
 switch (view) {
 case "home":
 return <HomeScreen navigate={navigate} />;
 case "report":
 return <ReportIssueScreen navigate={navigate} />;
 case "issue-form":
 return <IssueFormScreen navigate={navigate} issueType={type} />;
 case "mybus":
 return <MyBusScreen navigate={navigate} />;
 case "buspass":
 return <BusPassScreen navigate={navigate} />;
 case "requests":
 return <MyRequestsScreen navigate={navigate} />;
 case "request-detail":
 return <RequestDetailScreen navigate={navigate} requestId={id} />;
 case "lostfound":
 return <LostFoundScreen navigate={navigate} />;
 case "emergency":
 return <EmergencyScreen navigate={navigate} />;
 case "profile":
 return <ProfileScreen navigate={navigate} />;
 default:
 return <HomeScreen navigate={navigate} />;
 }
 };

 // Driver screens
 const renderDriverScreen = () => {
 return <DriverHome />;
 };

 // Admin screens
 const renderAdminScreen = () => {
 return <AdminHome />;
 };

 return (
 <div className="ms-app">
 <RoleSwitcher role={role} setRole={setRole} />
 <div className="ms-content">
 {role === "student" && renderStudentScreen()}
 {role === "driver" && renderDriverScreen()}
 {role === "admin" && renderAdminScreen()}
 </div>
 {role === "student" && <BottomNav currentView={view} navigate={navigate} />}
 {role === "driver" && <DriverNav currentView={view} navigate={navigate} />}
 {role === "admin" && <AdminNav currentView={view} navigate={navigate} />}
 {role === "student" && <ChatWidget />}
 </div>
 );
}
","import React from "react";
import ReactDOM from "react-dom/client";
import App from "./app";

ReactDOM.createRoot(document.getElementById("root")).render(<App />);
